<script>
'use strict';
/* =====================================================================
   Potentiometer voltage divider — interactive simulation
   Solver: modified nodal analysis (linear DC), device models as given:
   battery = ideal source + 0.2 Ω internal (Norton stamp),
   potentiometer = r1/r2 split at wiper, switches 0.001 Ω closed,
   capacitors open at DC. LEDs/diodes not present in this netlist.
   ===================================================================== */
const $ = id => document.getElementById(id);
const clamp = (v,lo,hi) => Math.min(hi, Math.max(lo, v));

const DEF = { batt: 9, potR: 10000, wiper: 0.5 }; // app defaults for missing values
const state = {
  mode: 'fixed',                                  // starts in Fixed, per brief
  sess: { batt: DEF.batt, potR: DEF.potR, wiper: DEF.wiper },
  touched: { batt: false, pot: false, wiper: false },
  switches: {},
  hotNet: null
};

/* ---------------- generic MNA solver ---------------- */
function gaussSolve(A, b){
  const n = b.length;
  const M = A.map((row,i) => row.concat([b[i]]));
  for (let col=0; col<n; col++){
    let piv = col;
    for (let r=col+1; r<n; r++) if (Math.abs(M[r][col]) > Math.abs(M[piv][col])) piv = r;
    if (Math.abs(M[piv][col]) < 1e-12) M[piv][col] = 1e-12;
    const tmp = M[col]; M[col] = M[piv]; M[piv] = tmp;
    for (let r=0; r<n; r++){
      if (r === col) continue;
      const f = M[r][col] / M[col][col];
      if (f === 0) continue;
      for (let c=col; c<=n; c++) M[r][c] -= f * M[col][c];
    }
  }
  const x = new Array(n).fill(0);
  for (let i=0; i<n; i++) x[i] = M[i][n] / M[i][i];
  return x;
}

function solveMNA(components, ref){
  const nodeSet = new Set();
  components.forEach(c => c.nodes.forEach(n => nodeSet.add(n)));
  const nonRef = [...nodeSet].filter(n => n !== ref);
  const idx = {}; nonRef.forEach((n,i) => idx[n] = i);
  const n = nonRef.length;
  const A = Array.from({length:n}, () => new Array(n).fill(0));
  const z = new Array(n).fill(0);
  const gi = name => (name === ref) ? -1 : idx[name];
  const stampG = (a,b,g) => {
    const ia = gi(a), ib = gi(b);
    if (ia >= 0) A[ia][ia] += g;
    if (ib >= 0) A[ib][ib] += g;
    if (ia >= 0 && ib >= 0){ A[ia][ib] -= g; A[ib][ia] -= g; }
  };
  const stampI = (from,to,i) => { // current source pushing i from `from` into `to`
    const ia = gi(from), ib = gi(to);
    if (ia >= 0) z[ia] -= i;
    if (ib >= 0) z[ib] += i;
  };
  components.forEach(c => {
    switch (c.type){
      case 'battery': {
        const r = 0.2, g = 1 / r;                 // ideal source + 0.2 Ω internal
        stampG(c.nodes[0], c.nodes[1], g);        // parallel conductance (Norton)
        stampI(c.nodes[1], c.nodes[0], c.value * g);
        break;
      }
      case 'resistor':
      case 'lamp':
        stampG(c.nodes[0], c.nodes[1], 1 / Math.max(c.value, 1e-6));
        break;
      case 'switch':
      case 'button':
        if (c.closed) stampG(c.nodes[0], c.nodes[1], 1 / 0.001);
        break; // open circuit otherwise
      case 'potentiometer': {
        const Rp = Math.max(c.value, 1e-3), p = clamp(c.position, 0, 1);
        const rA = Math.max((1 - p) * Rp, 1e-3);  // vcc -> wiper  (r1)
        const rB = Math.max(p * Rp, 1e-3);        // wiper -> gnd  (r2)
        stampG(c.nodes[0], c.nodes[1], 1 / rA);
        stampG(c.nodes[1], c.nodes[2], 1 / rB);
        c._r1 = rA; c._r2 = rB;
        break;
      }
      case 'capacitor': break;      // open circuit at DC
      case 'led': case 'diode':     // none in this netlist; mode included for completeness
        break;
    }
  });
  const x = n ? gaussSolve(A, z) : [];
  const V = name => (name === ref) ? 0 : x[idx[name]];
  return { V };
}

/* ---------------- circuit evaluation ---------------- */
let last = null;
function compute(){
  const comps = [
    { id:'B1',  type:'battery',      nodes:['vcc','gnd'],       value: state.sess.batt },
    { id:'RV1', type:'potentiometer',nodes:['vcc','n1','gnd'],  value: state.sess.potR, position: state.sess.wiper }
  ];
  const { V } = solveMNA(comps, 'gnd');
  const Vb = V('vcc'), Vn = V('n1');
  const r1 = comps[1]._r1, r2 = comps[1]._r2;
  const Ib  = (state.sess.batt - (Vb - V('gnd'))) / 0.2;        // delivered out of +
  const Ir1 = (Vb - Vn) / r1;                                   // into wiper end of r1
  const Ir2 = Vn / r2;
  const P_pot = (Vb - Vn) * Ir1 + Vn * Ir2;
  const P_src = state.sess.batt * Ib;
  return { Vb, Vn, Ib, Ir1, Ir2, r1, r2, P_pot, P_src };
}

/* ---------------- formatting ---------------- */
const fmtV = v => (Math.abs(v) < 5e-4 ? '0.00' : v.toFixed(2)) + ' V';
const fmtI = i => {
  const a = Math.abs(i);
  if (a < 1e-9)  return '0.000 mA';
  if (a < 1e-3)  return (i * 1e6).toFixed(1) + ' µA';
  return (i * 1e3).toFixed(2) + ' mA';
