const fmtR = r => r >= 1000 ? (r / 1000).toFixed(2) + ' kΩ' : r.toFixed(1) + ' Ω';
const fmtP = p => (p * 1000).toFixed(3) + ' mW';

/* ---------------- geometry / wiper layout ---------------- */
const POT_X = 320, POT_TOP = 148, POT_BOT = 380;
const wiperY = p => +(POT_BOT - clamp(p,0,1) * (POT_BOT - POT_TOP)).toFixed(2);

function zigPoints(x, y0, y1, amp, n){
  const pts = [[x, y0]];
  for (let i=1; i<n; i++){
    pts.push([x + (i % 2 ? amp : -amp), +(y0 + (y1 - y0) * i / n).toFixed(2)]);
  }
  pts.push([x, y1]);
  return pts;
}
const ZIG = zigPoints(POT_X, POT_TOP, POT_BOT, 13, 12);
$('potZig').setAttribute('points', ZIG.map(p => p.join(',')).join(' '));

