/* ---------------- current dots ---------------- */
function polyLen(pts){
  const cum = [0];
  for (let i=1; i<pts.length; i++){
    const dx = pts[i][0]-pts[i-1][0], dy = pts[i][1]-pts[i-1][1];
    cum.push(cum[i-1] + Math.hypot(dx, dy));
  }
  return cum;
}
function pointAt(pts, cum, s){
  const L = cum[cum.length-1];
  s = clamp(s, 0, L - 1e-6);
  let i = 1; while (cum[i] < s) i++;
  const seg = cum[i] - cum[i-1], f = seg > 0 ? (s - cum[i-1]) / seg : 0;
  return [ pts[i-1][0] + (pts[i][0]-pts[i-1][0]) * f, pts[i-1][1] + (pts[i][1]-pts[i-1][1]) * f ];
}
const TRACKS = [
  { pts: [[120,452],[120,88]] },                    // through the source, - to +
  { pts: [[120,88],[320,88],[320,148]] },           // top rail
  { pts: ZIG },                                     // through the divider
  { pts: [[320,380],[320,452]] },                   // bottom stub
  { pts: [[320,452],[120,452]] }                    // bottom rail back to source
];
TRACKS.forEach(t => { t.cum = polyLen(t.pts); t.len = t.cum[t.cum.length-1]; t.phase = 0; t.dots = []; });

const dotsGroup = $('dots');
TRACKS.forEach(t => {
  const count = Math.max(2, Math.round(t.len / 52));
  t.spacing = t.len / count;
  for (let i=0; i<count; i++){
    const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    c.setAttribute('r', 3);
    c.setAttribute('fill', '#DAFF33');
    c.setAttribute('opacity', '0.95');
    dotsGroup.appendChild(c);
    t.dots.push(c);
  }
});
const dotSpeed = I => clamp(16000 * Math.abs(I) + 4, 0, 90); // px per second, faster with I
let lastFrame = performance.now();
function tick(now){
  const dt = Math.min(0.05, (now - lastFrame) / 1000);
  lastFrame = now;
  const I = last ? last.Ib : 0;
  const sp = dotSpeed(I);
  const dir = I >= 0 ? 1 : -1;
  TRACKS.forEach(t => {
    const flowing = Math.abs(I) > 1e-9;
    if (flowing) t.phase = (t.phase + dir * sp * dt) % t.len;
    t.dots.forEach((c, i) => {
      if (!flowing){ c.setAttribute('display','none'); return; }
      c.removeAttribute('display');
      let s = (i * t.spacing + t.phase) % t.len; if (s < 0) s += t.len;
      const [x, y] = pointAt(t.pts, t.cum, s);
      c.setAttribute('cx', x.toFixed(1));
      c.setAttribute('cy', y.toFixed(1));
    });
  });
  requestAnimationFrame(tick);
}

